import { Avatar } from '@/registry/ndeko/ui/avatar';
import {
  Timeline,
  TimelineContent,
  TimelineHeader,
  TimelineIndicator,
  TimelineItem,
  TimelineSeparator,
  TimelineTitle,
} from '@/registry/ndeko/ui/timeline';

import { AgoTime } from './_parts/ago-time';
import { MARKER, MARKER_RAIL, MARKER_ROW } from './_parts/markers';

type Remark = {
  author: string;
  action: string;
  text: string;
  at: string;
};

const REVIEW_THREAD: Remark[] = [
  {
    author: 'Noor Rahimi',
    action: 'shared round two',
    text: 'Three label options for the cocoa tin. Option B keeps the oat stalk from the old pack.',
    at: '2026-11-12T11:55:00',
  },
  {
    author: 'Tobias Lindqvist',
    action: 'left a note',
    text: 'B reads best from the shelf. The weight line gets hard to read under 40 mm though.',
    at: '2026-11-12T13:10:00',
  },
  {
    author: 'Wanjiru Kamau',
    action: 'asked you to check it',
    text: 'Can you look at the clear zone around the barcode before Thursday?',
    at: '2026-11-12T14:15:00',
  },
  {
    author: 'Idris Okoye',
    action: 'approved option B',
    text: 'Approved with the larger weight line. It goes to the printer tonight.',
    at: '2026-11-12T14:50:00',
  },
];

const ROW = [
  MARKER_ROW,
  'group-data-[orientation=vertical]/timeline:not-last:pb-8',
].join(' ');

const PORTRAIT_FRAME = [MARKER, 'border-none bg-transparent'].join(' ');

export default function Timeline07() {
  return (
    <Timeline
      role='list'
      aria-label='Review of the Oatfield label'
      className='w-full max-w-md [--marker:1.5rem]'
    >
      {REVIEW_THREAD.map((remark, index) => {
        const step = index + 1;

        return (
          <TimelineItem
            key={remark.at}
            step={step}
            role='listitem'
            className={ROW}
          >
            <TimelineHeader>
              <TimelineIndicator className={PORTRAIT_FRAME}>
                <Avatar seed={remark.author} className='size-(--marker)' />
              </TimelineIndicator>
              <TimelineSeparator className={MARKER_RAIL} />
              <TimelineTitle className='mt-0.5'>
                {remark.author}{' '}
                <span className='text-muted-foreground font-normal'>
                  {remark.action}
                </span>
              </TimelineTitle>
            </TimelineHeader>
            <TimelineContent className='bg-foreground/[0.04] text-foreground mt-2 rounded-xl px-3 py-2.5'>
              {remark.text}
              <AgoTime at={remark.at} className='mt-1' />
            </TimelineContent>
          </TimelineItem>
        );
      })}
    </Timeline>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { TimelineDate } from '@/registry/ndeko/ui/timeline';

import { agoLabelOf, stampLabelOf } from './dates';

type AgoTimeProps = {
  at: string;
  className?: string;
};

export function AgoTime({ at, className }: AgoTimeProps) {
  return (
    <TimelineDate
      dateTime={at}
      title={stampLabelOf(at)}
      className={cn('mb-0', className)}
    >
      {agoLabelOf(at)}
    </TimelineDate>
  );
}

import { differenceInMinutes, format, parseISO } from 'date-fns';

/* Every time is read against one fixed moment and written without a time zone, so the server and the browser print the same labels. */
const NOW = '2026-11-12T15:00:00';

const MINUTES_PER_HOUR = 60;

const MINUTES_PER_DAY = 1440;

export function dayLabelOf(isoDay: string) {
  const day = parseISO(isoDay);
  return format(day, 'MMM d, yyyy');
}

export function stampLabelOf(isoTime: string) {
  const time = parseISO(isoTime);
  return format(time, "MMMM d, yyyy 'at' HH:mm");
}

function agoOf(count: number, unit: string) {
  if (count === 1) {
    return `1 ${unit} ago`;
  }
  return `${count} ${unit}s ago`;
}

export function agoLabelOf(isoTime: string) {
  const now = parseISO(NOW);
  const time = parseISO(isoTime);
  const minutes = differenceInMinutes(now, time);
  if (minutes < 1) {
    return 'Just now';
  }
  if (minutes < MINUTES_PER_HOUR) {
    return agoOf(minutes, 'minute');
  }
  if (minutes < MINUTES_PER_DAY) {
    const hours = Math.floor(minutes / MINUTES_PER_HOUR);
    return agoOf(hours, 'hour');
  }
  const days = Math.floor(minutes / MINUTES_PER_DAY);
  return agoOf(days, 'day');
}

/*
 * A marker wider than the 16px dot. Its size is --marker, set on the timeline: the row, the marker
 * and the rail are all placed from it, so the marker keeps its left edge on the edge of the piece.
 */
export const MARKER_ROW =
  'group-data-[orientation=vertical]/timeline:ms-[calc(var(--marker)_+_1rem)]';

export const MARKER = [
  'flex size-(--marker) items-center justify-center',
  'group-data-[orientation=vertical]/timeline:-left-[calc(var(--marker)/2_+_1rem)]',
].join(' ');

export const MARKER_RAIL = [
  'group-data-[orientation=vertical]/timeline:-left-[calc(var(--marker)/2_+_1rem)]',
  'group-data-[orientation=vertical]/timeline:h-[calc(100%_-_var(--marker)_-_0.25rem)]',
  'group-data-[orientation=vertical]/timeline:translate-y-[calc(var(--marker)_+_0.125rem)]',
].join(' ');
